#pragma once
#include <wtsapi32.h>
#include <map>
#include <filesystem>
// File IO runs under the actual interactive-session user, even for SYSTEM capture.
struct ClipboardUser {
 HANDLE token=nullptr;bool impersonating=false;
 ClipboardUser(){HANDLE current=nullptr;if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&current))throw std::runtime_error("CLIPBOARD_USER_TOKEN");DWORD size=0;GetTokenInformation(current,TokenUser,nullptr,0,&size);std::vector<unsigned char> buffer(size);bool system=GetTokenInformation(current,TokenUser,buffer.data(),size,&size)&&IsWellKnownSid(((TOKEN_USER*)buffer.data())->User.Sid,WinLocalSystemSid);CloseHandle(current);if(system){DWORD session=0;if(!ProcessIdToSessionId(GetCurrentProcessId(),&session)||!session||!WTSQueryUserToken(session,&token)||!ImpersonateLoggedOnUser(token)){if(token)CloseHandle(token);token=nullptr;throw std::runtime_error("CLIPBOARD_INTERACTIVE_USER_UNAVAILABLE");}impersonating=true;}}
 ~ClipboardUser(){if(impersonating)RevertToSelf();if(token)CloseHandle(token);}
};
struct ClipboardFiles {
 struct File{HANDLE handle=INVALID_HANDLE_VALUE;uint64_t size=0,offset=0;bool writing=false;std::wstring path;FILETIME modified{};};std::map<std::string,File> files;std::wstring directory;uint64_t total=0;
 ~ClipboardFiles(){for(auto &entry:files)if(entry.second.handle!=INVALID_HANDLE_VALUE)CloseHandle(entry.second.handle);for(auto &entry:files){auto&f=entry.second;if(f.writing){DeleteFileW(f.path.c_str());auto at=f.path.find_last_of(L"\\");if(at!=std::wstring::npos)RemoveDirectoryW(f.path.substr(0,at).c_str());}}if(!directory.empty())RemoveDirectoryW(directory.c_str());}
 static std::string id(){GUID g{};if(FAILED(CoCreateGuid(&g)))throw std::runtime_error("CLIPBOARD_TOKEN");wchar_t s[40];StringFromGUID2(g,s,40);return utf8(s).substr(1,36);}
 static uint64_t size(const BY_HANDLE_FILE_INFORMATION&i){return ((uint64_t)i.nFileSizeHigh<<32)|i.nFileSizeLow;}
 json add(const std::wstring&path){ClipboardUser user;if(files.size()>=64)throw std::runtime_error("CLIPBOARD_FILE_LIMIT");HANDLE h=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL|FILE_FLAG_OPEN_REPARSE_POINT,nullptr);if(h==INVALID_HANDLE_VALUE)throw std::runtime_error("CLIPBOARD_FILE_ACCESS_DENIED");BY_HANDLE_FILE_INFORMATION info{};if(!GetFileInformationByHandle(h,&info)||(info.dwFileAttributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT))||GetFileType(h)!=FILE_TYPE_DISK||total+size(info)>512*1024*1024){CloseHandle(h);throw std::runtime_error("CLIPBOARD_FILE_UNSUPPORTED");}auto token=id();files[token]={h,size(info),0,false,path,info.ftLastWriteTime};total+=size(info);auto slash=path.find_last_of(L"\\/");return {{"token",token},{"name",utf8(path.substr(slash==std::wstring::npos?0:slash+1).c_str())},{"size",size(info)}};}
 static void cacheBudget(const std::wstring&base,uint64_t incoming){
  namespace fs=std::filesystem;uint64_t bytes=0;size_t entries=0;std::error_code ec;
  for(const auto&folder:fs::directory_iterator(base,ec)){if(ec)throw std::runtime_error("CLIPBOARD_CACHE_CHECK");auto name=folder.path().filename().wstring();if(name.rfind(L"CAgent-Clipboard-",0)!=0)continue;auto attributes=GetFileAttributesW(folder.path().c_str());if(attributes==INVALID_FILE_ATTRIBUTES||(attributes&FILE_ATTRIBUTE_REPARSE_POINT)||!(attributes&FILE_ATTRIBUTE_DIRECTORY))continue;
   for(auto it=fs::recursive_directory_iterator(folder.path(),fs::directory_options::none,ec);!ec&&it!=fs::recursive_directory_iterator();it.increment(ec)){if(++entries>4096)throw std::runtime_error("CLIPBOARD_CACHE_FULL");auto a=GetFileAttributesW(it->path().c_str());if(a==INVALID_FILE_ATTRIBUTES)throw std::runtime_error("CLIPBOARD_CACHE_CHECK");if(a&FILE_ATTRIBUTE_REPARSE_POINT){it.disable_recursion_pending();continue;}if(!(a&FILE_ATTRIBUTE_DIRECTORY)){bytes+=it->file_size(ec);if(ec||bytes+incoming>512ULL*1024*1024)throw std::runtime_error("CLIPBOARD_CACHE_FULL");}}if(ec)throw std::runtime_error("CLIPBOARD_CACHE_CHECK");
  }if(ec)throw std::runtime_error("CLIPBOARD_CACHE_CHECK");
 }
 json begin(const std::string&name,uint64_t length){ClipboardUser user;PWSTR cacheBase=nullptr;if(FAILED(SHGetKnownFolderPath(FOLDERID_LocalAppData,0,user.token,&cacheBase)))throw std::runtime_error("CLIPBOARD_USER_DIRECTORY");std::wstring cacheRoot(cacheBase);CoTaskMemFree(cacheBase);cacheBudget(cacheRoot,length);if(files.size()>=64||total+length>512*1024*1024)throw std::runtime_error("CLIPBOARD_FILE_LIMIT");if(name.empty()||name.find_first_of("\\/:*?\"<>|")!=std::string::npos||name.back()=='.'||name.back()==' ')throw std::runtime_error("CLIPBOARD_FILE_NAME");for(unsigned char c:name)if(c<32)throw std::runtime_error("CLIPBOARD_FILE_NAME");auto wide=DesktopClipboardWide(name);if(directory.empty()){PWSTR base=nullptr;if(FAILED(SHGetKnownFolderPath(FOLDERID_LocalAppData,0,user.token,&base)))throw std::runtime_error("CLIPBOARD_USER_DIRECTORY");directory=std::wstring(base)+L"\\CAgent-Clipboard-"+DesktopClipboardWide(id());CoTaskMemFree(base);if(!CreateDirectoryW(directory.c_str(),nullptr)){directory.clear();throw std::runtime_error("CLIPBOARD_DIRECTORY_CREATE");}}
  auto transferDirectory=directory+L"\\"+DesktopClipboardWide(id());if(!CreateDirectoryW(transferDirectory.c_str(),nullptr))throw std::runtime_error("CLIPBOARD_DIRECTORY_CREATE");auto path=transferDirectory+L"\\"+wide;HANDLE h=CreateFileW(path.c_str(),GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(h==INVALID_HANDLE_VALUE)throw std::runtime_error("CLIPBOARD_FILE_CREATE");auto token=id();files[token]={h,length,0,true,path,{}};total+=length;return {{"fileToken",token},{"chunkSize",65536}};
 }
 static std::wstring DesktopClipboardWide(const std::string&s){int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),(int)s.size(),nullptr,0);if(!n)throw std::runtime_error("CLIPBOARD_UTF8");std::wstring w(n,L'\0');MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),(int)s.size(),w.data(),n);return w;}
 json chunk(const json&c){ClipboardUser user;auto it=files.find(c.at("fileToken").get<std::string>());if(it==files.end())throw std::runtime_error("CLIPBOARD_FILE_TOKEN");auto&f=it->second;auto offset=c.at("offset").get<uint64_t>();if(offset>f.size)throw std::runtime_error("CLIPBOARD_FILE_OFFSET");LARGE_INTEGER where{};where.QuadPart=offset;if(!SetFilePointerEx(f.handle,where,nullptr,FILE_BEGIN))throw std::runtime_error("CLIPBOARD_FILE_SEEK");
  if(f.writing){auto hex=c.at("hex").get<std::string>();if(offset!=f.offset||hex.size()>4096||hex.size()%2||offset+hex.size()/2>f.size)throw std::runtime_error("CLIPBOARD_FILE_CHUNK");std::vector<unsigned char>b(hex.size()/2);auto digit=[](char c)->int{if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;throw std::runtime_error("CLIPBOARD_FILE_HEX");};for(size_t i=0;i<b.size();i++)b[i]=(unsigned char)((digit(hex[i*2])<<4)|digit(hex[i*2+1]));DWORD n=0;if(!WriteFile(f.handle,b.data(),(DWORD)b.size(),&n,nullptr)||n!=b.size())throw std::runtime_error("CLIPBOARD_FILE_WRITE");f.offset+=n;return {{"offset",f.offset}};}
  BY_HANDLE_FILE_INFORMATION before{},after{};if(!GetFileInformationByHandle(f.handle,&before)||size(before)!=f.size||CompareFileTime(&before.ftLastWriteTime,&f.modified))throw std::runtime_error("CLIPBOARD_FILE_CHANGED");std::vector<unsigned char>b((size_t)std::min<uint64_t>(2048,f.size-offset));DWORD n=0;if(!ReadFile(f.handle,b.data(),(DWORD)b.size(),&n,nullptr)||!GetFileInformationByHandle(f.handle,&after)||size(after)!=f.size||CompareFileTime(&after.ftLastWriteTime,&f.modified))throw std::runtime_error("CLIPBOARD_FILE_CHANGED");const char*d="0123456789abcdef";std::string hex;for(DWORD i=0;i<n;i++){hex+=d[b[i]>>4];hex+=d[b[i]&15];}return {{"hex",hex},{"offset",offset+n},{"done",offset+n==f.size}};
 }
 json paths(const json&tokens){ClipboardUser user;if(!tokens.is_array()||tokens.empty()||tokens.size()>64)throw std::runtime_error("CLIPBOARD_FILES_INVALID");json paths=json::array();for(const auto&t:tokens){auto i=files.find(t.get<std::string>());if(i==files.end()||!i->second.writing||i->second.offset!=i->second.size)throw std::runtime_error("CLIPBOARD_UPLOAD_INCOMPLETE");if(!FlushFileBuffers(i->second.handle))throw std::runtime_error("CLIPBOARD_FILE_FLUSH");i->second.writing=false;BY_HANDLE_FILE_INFORMATION info{};if(!GetFileInformationByHandle(i->second.handle,&info))throw std::runtime_error("CLIPBOARD_FILE_STATUS");i->second.modified=info.ftLastWriteTime;paths.push_back(utf8(i->second.path.c_str()));}return paths;}
};


